// English glossary: same structure and lesson slugs as the Russian one.
export const glossaryEn = [
  {
    group: 'Statistics',
    categories: [
      { id: 'describe', title: 'Describing data', desc: 'Center, spread and shape of a distribution' },
      { id: 'probability', title: 'Probability', desc: 'The language of uncertainty and why averages are stable' },
      { id: 'inference', title: 'Estimation and hypothesis testing', desc: 'Judging the whole from a sample and reading A/B tests' },
      { id: 'models', title: 'Relationships and models', desc: 'Relationships between variables and model quality' },
      { id: 'traps', title: 'Interpretation traps', desc: 'Where conclusions from data most often break' },
      { id: 'timeseries', title: 'Time series and forecasting', desc: 'The structure of a series over time and checking forecasts' },
    ],
    terms: [
      { term: 'Mean', def: 'The sum of all values divided by their count. It marks the centre of gravity of the data: if every observation were identical, each one would equal the mean.', formula: '\\bar{x} = \\frac{1}{n}\\sum_{i=1}^{n} x_i', aliases: ['average', 'arithmetic mean'], lesson: 'center-measures', cat: 'describe' },
      { term: 'Median', def: 'The value that splits the ordered list in half: half the observations fall below it, half above. With an even count you take the midpoint of the two central values.', aliases: ['middle value'], lesson: 'center-measures', cat: 'describe' },
      { term: 'Mode', def: 'The value that occurs most often. It is the only measure of centre that works for categories — the best-selling product, the most common payment method.', aliases: [], lesson: 'center-measures', cat: 'describe' },
      { term: 'Variance', def: 'The average squared deviation of values from their mean: the more spread out the data, the larger it gets. It is measured in squared original units — dollars², minutes².', formula: '\\sigma^2 = \\frac{1}{n}\\sum (x_i - \\bar{x})^2', aliases: ['dispersion'], lesson: 'spread', cat: 'describe' },
      { term: 'Standard deviation (σ)', def: 'The square root of the variance: the typical distance from the mean to a single observation, in the same units as the data. For a normal distribution about 68% of values lie within ±1σ of the mean and 95% within ±2σ.', formula: '\\sigma = \\sqrt{\\frac{1}{n}\\sum (x_i - \\bar{x})^2}', aliases: ['std', 'sd', 'sigma'], lesson: 'spread', cat: 'describe' },
      { term: 'Percentile / quartile', def: 'The value below which a given share of the data lies: p95 is the threshold that 95% of observations do not exceed. Quartiles are the 25th, 50th and 75th percentiles (Q1, median, Q3).', aliases: ['quantile', 'p95', 'p99'], lesson: 'percentiles', cat: 'describe' },
      { term: 'Normal distribution', def: 'A symmetric bell-shaped distribution fully described by two numbers: the mean μ (where the peak sits) and the standard deviation σ (how wide the bell is). The 68-95-99.7 rule: ±1σ, ±2σ and ±3σ contain 68%, 95% and 99.7% of values.', aliases: ['gaussian', 'bell curve'], lesson: 'normal-distribution', cat: 'describe' },
      { term: 'Skewness', def: 'A measure of asymmetry in a distribution: one tail stretches further than the other. Under right skew, rare large values pull the mean up above the median.', aliases: ['skew', 'long tail'], lesson: 'skew-tail', cat: 'describe' },
      { term: 'Probability', def: 'A number from 0 to 1 saying how expected an event is: 0 means impossible, 1 means certain. Under the frequentist reading it is the share of cases in which the event occurs if the trial is repeated many times.', aliases: [], lesson: 'probability-basics', cat: 'probability' },
      { term: 'Law of large numbers', def: 'As trials accumulate, the observed share converges to the true probability. The law describes the behaviour of the average over a long run and says nothing about any individual trial.', aliases: ['LLN'], lesson: 'probability-lln', cat: 'probability' },
      { term: 'Conditional probability', def: 'The probability of event A given that event B has already happened, written P(A|B). It differs from the reverse quantity P(B|A) — these are different numbers.', formula: 'P(A|B) = \\frac{P(A \\cap B)}{P(B)}', aliases: [], lesson: 'conditional-bayes', cat: 'probability' },
      { term: 'Bayes’ theorem', def: 'The rule for updating a probability once new data arrives: P(A|B) = P(B|A)·P(A) / P(B). It accounts for the base rate P(A) — how common the event is before any evidence.', formula: 'P(A|B) = \\frac{P(B|A)\\cdot P(A)}{P(B)}', aliases: ['bayes'], lesson: 'conditional-bayes', cat: 'probability' },
      { term: 'CLT', def: 'The central limit theorem: take samples from almost any distribution and compute the mean of each, and the distribution of those means tends toward normal while its spread shrinks as σ/√n.', formula: '\\sigma_{\\bar{x}} = \\frac{\\sigma}{\\sqrt{n}}', aliases: ['central limit theorem'], lesson: 'clt', cat: 'probability' },
      { term: 'Standard error', def: 'The standard deviation of the estimate itself rather than of the data: how much the mean varies from one sample to another. For a mean, SE = σ/√n.', formula: 'SE = \\frac{\\sigma}{\\sqrt{n}}', aliases: ['SE'], lesson: 'sampling-statistic', cat: 'inference' },
      { term: 'Confidence interval', def: 'A range of plausible values for the quantity being estimated. The interpretation applies to the method: repeat the experiment many times, build a 95% interval each time, and about 95% of those intervals will cover the true value.', formula: '\\bar{x} \\pm z \\cdot SE', aliases: ['CI'], lesson: 'confidence-intervals', cat: 'inference' },
      { term: 'Bootstrap', def: 'Estimating uncertainty without formulas: from the sample you have, repeatedly draw a new sample of the same size with replacement and observe how the statistic of interest varies.', aliases: [], lesson: 'bootstrap', cat: 'inference' },
      { term: 'Null hypothesis (H0)', def: 'The claim that there is no effect and the observed difference is chance. Testing proceeds by contradiction: you compute how implausible the observed data would be in a world without the effect.', aliases: ['null'], lesson: 'hypothesis-intro', cat: 'inference' },
      { term: 'p-value', def: 'The probability of seeing a result at least this extreme if there is genuinely no effect. It is not the probability that the hypothesis is true, and it is not the size of the effect.', aliases: ['significance'], lesson: 'hypothesis-test', cat: 'inference' },
      { term: 'Type I error (α)', def: 'A false positive: the test rejected a true null hypothesis, declaring an effect that does not exist. The level α is chosen in advance and is the share of such errors accepted (usually 0.05).', aliases: ['alpha', 'false positive'], lesson: 'hypothesis-test', cat: 'inference' },
      { term: 'Type II error (β)', def: 'A false negative: the effect is genuinely there but the test failed to detect it. The converse — detecting an effect that exists — is called power and equals 1−β.', formula: '\\text{power} = 1 - \\beta', aliases: ['beta', 'false negative'], lesson: 'hypothesis-test', cat: 'inference' },
      { term: 'Power', def: 'The probability of detecting an effect of a given size, assuming it is genuinely there. It depends on the effect size, the spread of the data, the sample size and the chosen α.', formula: '1 - \\beta', aliases: ['sensitivity'], lesson: 'power-sample-size', cat: 'inference' },
      { term: 't-test', def: 'A test comparing the means of two groups: it measures the observed difference against the standard error of that difference. It assumes independent observations and roughly normal sample means.', formula: 't = \\frac{\\bar{x}_1 - \\bar{x}_2}{SE_{\\text{diff}}}', aliases: ['student'], lesson: 'stat-criteria', cat: 'inference' },
      { term: 'Multiple comparisons', def: 'Testing many hypotheses at once — several metrics, segments or variants. The risk of a false positive accumulates: with 20 independent tests at α=0.05, at least one false "significant" appears about 64% of the time.', formula: 'P(\\text{at least one error}) = 1 - (1-\\alpha)^m', aliases: ['bonferroni', 'FDR'], lesson: 'multiple-comparisons', cat: 'inference' },
      { term: 'Correlation (r)', def: 'A number from −1 to +1 describing the strength and direction of a linear relationship. Zero means no linear relationship, not the absence of any relationship.', aliases: ['pearson', 'spearman'], lesson: 'correlation-types', cat: 'models' },
      { term: 'Regression / OLS', def: 'A method that fits a line (or a more complex shape) so the sum of squared deviations of the points from it is as small as possible. The slope shows how much y changes on average when x rises by one.', formula: 'y = b_0 + b_1 x', aliases: ['linear regression', 'least squares'], lesson: 'regression', cat: 'models' },
      { term: 'Simpson’s paradox', def: 'A relationship visible in the aggregate reverses inside every subgroup. The cause is a hidden factor distributed unevenly across the groups.', aliases: ['simpson'], lesson: 'simpson-paradox', cat: 'traps' },
      { term: 'Overfitting', def: 'The model learned the random noise of the training data rather than the pattern: excellent results there, poor results on new data. It shows up as a gap between training and hold-out performance.', aliases: ['train test'], lesson: 'overfitting', cat: 'models' },
      { term: 'Precision / Recall', def: 'Precision — of the items the model assigned to a class, what share was assigned correctly. Recall — what share of the items actually in that class the model found.', formula: '\\text{precision} = \\frac{TP}{TP+FP},\\quad \\text{recall} = \\frac{TP}{TP+FN}', aliases: [], lesson: 'confusion-matrix', cat: 'models' },
      { term: 'ROC / AUC', def: 'The ROC curve shows how the shares of true positives and false positives relate as the classifier threshold is swept across its whole range. AUC is the area under that curve: 1.0 is perfect, 0.5 is coin-flip guessing.', aliases: [], lesson: 'roc', cat: 'models' },
      { term: 'Survivorship bias', def: 'A distortion where conclusions are drawn only from the cases that survived into the data, while those that dropped out are invisible.', aliases: [], lesson: 'survivorship-bias', cat: 'traps' },
      { term: 'Goodhart’s law', def: 'Once a measure becomes a target, it starts being optimized directly and stops reflecting whatever it was introduced to capture.', aliases: ['goodhart'], lesson: 'goodhart', cat: 'traps' },
      { term: 'Time series', def: 'A sequence of metric values ordered in time at a constant step. Neighboring observations depend on each other, so the usual methods built for independent data cannot be applied to a series without caveats.', aliases: ['series'], lesson: 'ts-decomposition', cat: 'timeseries' },
      { term: 'Trend and seasonality', def: 'Two regular components of a series: the trend is slow directional movement, seasonality is oscillation with a known period (day of week, month of year). What remains after removing them is treated as noise.', formula: 'y = T + S + E', aliases: ['decomposition', 'seasonality', 'trend'], lesson: 'ts-decomposition', cat: 'timeseries' },
      { term: 'Autocorrelation', def: 'The correlation of a series with itself shifted a few steps back. It breaks the assumption of independent observations: standard errors come out too small and confidence intervals narrower than they should be.', formula: 'r_k = corr(y_t, y_{t-k})', aliases: ['ACF', 'correlogram', 'lag'], lesson: 'autocorrelation', cat: 'timeseries' },
      { term: 'Stationarity', def: 'The property of a series whose mean, spread and dependence structure do not change over time. Most forecasting models require it: only then does what was learned from the past carry over to the future.', aliases: ['Dickey-Fuller', 'ADF'], lesson: 'stationarity', cat: 'timeseries' },
      { term: 'Differencing', def: 'Moving from the values of a series to their changes. It removes the trend and makes the series stationary; a seasonal difference (subtracting the value one period earlier) removes the cycle. The I in ARIMA.', formula: 'Δy_t = y_t − y_{t−1}', aliases: ['first difference', 'seasonal difference'], lesson: 'stationarity', cat: 'timeseries' },
      { term: 'Exponential smoothing', def: 'A forecast from a weighted past, where the weight of observations decays geometrically with age. The Holt-Winters extension keeps level, trend and seasonality as separate components and extends each of them.', formula: 'L_t = α·y_t + (1−α)·L_{t−1}', aliases: ['ETS', 'Holt-Winters'], lesson: 'smoothing-forecast', cat: 'timeseries' },
      { term: 'ARIMA / SARIMA / SARIMAX', def: 'A family of models that describe a series through its past: AR is dependence on past values, I is differencing, MA is a correction for past errors. S adds the same mechanisms at the seasonal lag, X adds external features (promos, holidays) whose future values are known in advance.', formula: '(p,d,q)(P,D,Q)ₘ', aliases: ['arima', 'sarima', 'sarimax'], lesson: 'arima-family', cat: 'timeseries' },
      { term: 'Forecast backtest', def: 'Checking a forecast on history: training only on data before a cutoff and comparing with the actuals after it. The cutoff is moved several times, because an evaluation on one split is an evaluation on one observation.', aliases: ['backtest', 'rolling origin'], lesson: 'forecast-backtest', cat: 'timeseries' },
      { term: 'MAE / RMSE / MAPE', def: 'Forecast error metrics: MAE is the average miss in the metric\'s units, RMSE adds a heavier penalty for large misses, MAPE is the error as a percentage of the actual. MAPE is undefined at zero values and asymmetric; for such series MASE is used — the error divided by the error of a naive forecast.', formula: 'MAE = (1/n)·Σ|y − ŷ|', aliases: ['MASE', 'forecast metrics'], lesson: 'forecast-backtest', cat: 'timeseries' },
    ],
  },
  {
    group: 'Business metrics',
    categories: [
      { id: 'framework', title: 'North Star and guardrails', desc: 'What counts as success and what it must not cost' },
      { id: 'acquisition', title: 'Acquisition', desc: 'How people find the product and what it costs to bring them in', step: 1 },
      { id: 'activation', title: 'Activation and conversion', desc: 'Whether a newcomer reached first value', step: 2 },
      { id: 'retention', title: 'Engagement and retention', desc: 'Whether people come back, and how often', step: 3 },
      { id: 'revenue', title: 'Monetization', desc: 'How much money the audience brings', step: 4 },
      { id: 'subscription', title: 'Subscriptions and contracts', desc: 'Recurring revenue and how it moves across customers', step: 5 },
      { id: 'referral', title: 'Loyalty and referral', desc: 'Whether customers are satisfied and bring others', step: 6 },
      { id: 'unit', title: 'Unit economics', desc: 'Whether a customer pays back over their lifetime', step: 7 },
      { id: 'platform', title: 'Marketplaces and operations', desc: 'Platform turnover, take and fulfilment quality' },
      { id: 'concepts', title: 'Business concepts', desc: 'Terms that show up next to metrics' },
    ],
    terms: [
      { term: 'North Star Metric', def: 'The metric a team picks as its main one: it reflects the value users receive and leads revenue. It sits at the top of the metric tree, with the rest broken out as its drivers.', aliases: ['NSM'], id: 'north-star', cat: 'framework', case: 'A grocery delivery service picked orders delivered on time per week as its main metric. Signups and installs can be pumped up with ads, while an order that arrives on time means the customer got what they came for. Of 12,400 orders in a week, 11,200 arrived within the promised window, and that is the NSM value.' },
      { term: 'Guardrail metrics', def: 'Limit metrics that watch whether a gain in the target number is being bought with damage elsewhere. They are fixed before the experiment starts and reviewed together with the target metric.', aliases: ['counter-metrics'], lesson: 'goodhart', id: 'guardrails', cat: 'framework', case: 'A team tests a pushy discount pop-up. The target metric is order conversion, the guardrails are the cancellation rate and newsletter unsubscribes. Conversion is up 3% relative to control, unsubscribes doubled, and the pop-up does not ship even though the target metric is green.' },
      { term: 'CPM', def: 'Cost per mille — what an advertiser pays per thousand ad impressions. The base price of reach campaigns. It is easy to confuse with RPM, which counts what a platform or creator earns after the platform\'s cut.', formula: 'CPM = spend / impressions × 1000', aliases: ['cost per mille'], id: 'cpm', cat: 'acquisition', case: 'A reach campaign got 2 million impressions for $6,000: CPM is $3. At 0.5% CTR that is 10,000 clicks at $0.60 each. A low CPM says nothing about quality: if the impressions went to the wrong audience, clicks and orders come out expensive.' },
      { term: 'CTR', def: 'Click-through rate — clicks as a share of impressions of an ad, email or link. It measures appeal, not outcome.', formula: 'CTR = clicks / impressions', aliases: ['click-through rate'], metric: 'ctr', id: 'ctr', cat: 'acquisition', case: 'A banner was shown 50,000 times and clicked 600 times: CTR is 1.2%. A version with a loud headline got 2% clicks but fewer purchases. CTR measures the urge to click; what happened after the click is conversion\'s job.' },
      { term: 'CPC', def: 'Cost per click — the price of a single click on an ad. It is set in an auction and depends not only on the bid but on ad quality.', formula: 'CPC = spend / clicks', aliases: ['cost per click'], metric: 'cpc', id: 'cpc', cat: 'acquisition', case: 'In a week a search campaign got 4,000 clicks for $6,000: CPC is $1.50. At 2% click-to-order conversion one order costs $75. The campaign is then judged by whether the order margin covers that $75.' },
      { term: 'CPI', def: 'Cost per install — the cost of a single app install. The base metric of paid traffic in mobile products.', formula: 'CPI = acquisition spend / installs', aliases: ['cost per install'], id: 'cpi', cat: 'acquisition', case: 'A campaign on an ad network cost $12,000 and brought 6,000 installs: CPI is $2. An install is not yet a user: if half of them register, a registration costs $4.' },
      { term: 'CAC', def: 'The full cost of acquiring one new customer: marketing and sales budget divided by the number acquired. Computed over paid channels.', formula: 'CAC = acquisition spend / new customers acquired', aliases: ['acquisition cost'], metric: 'cac', id: 'cac', cat: 'acquisition', case: 'In September the company spent $120,000 on ads and $30,000 on the sales team, and got 1,000 new paying customers. CAC = $150,000 / 1,000 = $150. Counting ads alone gives $120, and acquisition looks cheaper than it is.' },
      { term: 'ROAS', def: 'Return on ad spend — how much revenue each unit of ad budget brings back: ROAS of 4 means four in revenue per one spent. Its inverse is the ad-cost share of revenue.', formula: 'ROAS = revenue from ads / ad spend', aliases: ['return on ad spend'], metric: 'roas', id: 'roas', cat: 'acquisition', case: 'A store spent $20,000 on ads and got $80,000 of orders from them. ROAS is 4, the ad-cost share is 25%. At a 20% margin those sales leave $16,000 of gross profit, less than the ad spend.' },
      { term: 'TAC', def: 'Traffic acquisition cost — what a platform pays for incoming traffic: to partners for being the default search and to network partners for showing its ads.', aliases: ['traffic acquisition cost'], id: 'tac', cat: 'acquisition', case: 'A search engine made $1bn in ad revenue in a quarter and paid $200m of it to partners: browsers for default search and websites for showing its ads. TAC is $200m, 20% of ad revenue. If that share rises, traffic is getting more expensive faster than revenue grows.' },
      { term: 'Conversion Rate (CR)', def: 'The share of users who reached a target action, out of those who had the chance to take it. It needs its base spelled out: "visit to order" and "cart to order" are different quantities.', formula: 'CR = target actions / users who could take them', aliases: ['conversion'], metric: 'conversion-rate', id: 'conversion-rate', cat: 'activation', case: 'In a week an online store had 20,000 visitors, and 600 of them placed an order: visitor-to-order conversion is 3%. 1,500 people added something to the cart, so cart-to-order conversion is 40%. Both numbers are correct, which is why the base is always stated.' },
      { term: 'Activation Rate', def: 'The share of new users who reach the key action after which the product starts delivering value: the first order, the first project, the first message. The activation point is picked from data: it is the action after which retention is noticeably higher.', formula: 'activation = activated users / signups', aliases: ['activation', 'aha moment'], metric: 'activation-rate', id: 'activation-rate', cat: 'activation', case: 'Of 8,000 people who signed up for a task manager in a week, 2,800 created a first project within a day: activation is 35%. 60% of activated users come back in week two versus 8% of the rest, which is why this action was chosen as the activation point.' },
      { term: 'Time to Value', def: 'The time from signup to the moment a user first gets value from the product. It is measured as a median over those who got there, next to the share who never did: without it the median hides the problem.', formula: 'TTV = median(first value − signup)', aliases: ['ttv', 'time to first value'], metric: 'ttv', id: 'ttv', cat: 'activation', case: 'In an email marketing service the median from signup to the first sent campaign was 2 days, and 45% of newcomers sent none within a month. After ready-made templates were added to onboarding, the median fell to 40 minutes and the share who never got there dropped to 30%.' },
      { term: 'Trial → Paid', def: 'Conversion from a free trial into a paying subscription. It depends heavily on the entry terms: a card-required trial converts better but brings fewer people in.', formula: 'conversion = paid subscriptions / trials started', aliases: ['trial to paid'], metric: 'trial-to-paid', id: 'trial-paid', cat: 'activation', case: 'In August 3,000 people started a trial and 540 paid after it: trial-to-paid is 18%. Requiring a card up front means fewer trials and a higher paid share. Such variants are compared by payments per 1,000 visitors.' },
      { term: 'Look-to-Book', def: 'The ratio of bookings to search sessions in travel services. Low values are normal for the industry: people compare options, dates and prices at length before buying.', formula: 'look-to-book = bookings / search sessions', aliases: [], id: 'look-to-book', cat: 'activation', case: 'In a month a hotel booking service handled 400,000 search sessions and got 6,000 bookings: look-to-book is 1.5%. For travel that is normal: people search many times before settling on dates and a hotel.' },
      { term: 'DAU / MAU', def: 'The count of unique users who took a target action in a day (DAU) and in a month (MAU). Their ratio is called stickiness and reads as "how many days a month a user shows up": 0.2 is roughly 6 days out of 30.', formula: 'stickiness = DAU / MAU', aliases: ['active users', 'stickiness'], metric: 'dau-mau', id: 'dau-mau', cat: 'retention', case: 'In September a note-taking app averaged 18,000 active users a day and 90,000 over the month. Stickiness is 0.2: a typical user opens the app about 6 days out of 30.' },
      { term: 'Retention', def: 'The share of a cohort that returns to the product after a given amount of time from first contact. It is computed by cohorts — groups that arrived in the same period.', formula: 'retention = returning cohort members / cohort size', aliases: [], metric: 'retention-n-day', id: 'retention', cat: 'retention', case: 'Of 5,000 people who signed up in March, 1,400 were active again in April. Month-1 retention of the March cohort is 28%. Compare it with the same checkpoint for the April and May cohorts, not with the overall active count.' },
      { term: 'D1 / D7 / D30', def: 'Retention on day 1, 7 and 30 after install: the share of a cohort that returns to the product on that day. The standard checkpoints of mobile analytics.', formula: 'Dn = users returning on day n / cohort size', aliases: ['retention day'], metric: 'retention-n-day', id: 'd1-d7-d30', cat: 'retention', case: 'On Monday 10,000 people installed a game. On Tuesday 4,000 of them came back, the next Monday 1,500, and 30 days later 500. D1 is 40%, D7 15%, D30 5%.' },
      { term: 'Repeat Purchase Rate', def: 'The share of buyers who make another purchase within a set window after the first one. For stores and delivery it is the main retention metric: app visits without an order say little.', formula: 'repeat rate = repeat buyers / first-time buyers', aliases: ['repeat rate'], metric: 'repeat-rate', id: 'repeat-rate', cat: 'retention', case: 'In June 4,000 people placed a first order with a flower delivery service, and 600 ordered again within 90 days: repeat rate is 15%. Compare it within the category: flowers are bought for occasions, groceries every week, and their norms differ.' },
      { term: 'Churn', def: 'The share of customers or revenue lost over a period. At 5% monthly churn the average customer life is about 20 months (1 / 0.05).', formula: 'churn = customers lost in period / customers at period start', aliases: [], metric: 'churn-rate', id: 'churn', cat: 'retention', case: 'On September 1 a streaming service had 40,000 subscribers, and 2,000 of them cancelled during the month. Churn is 5% a month. September\'s new subscribers stay out of the denominator, otherwise fast growth masks existing customers leaving.' },
      { term: 'ARPU / ARPPU', def: 'Average revenue per user (ARPU) and, separately, per paying user (ARPPU). The gap between them shows what share of the audience pays.', formula: 'ARPU = revenue / all users; ARPPU = revenue / paying users', aliases: [], metric: 'arpu', id: 'arpu', cat: 'revenue', case: 'A mobile game had 200,000 active players in a month, $300,000 in revenue and 6,000 payers. ARPU is $1.50, ARPPU is $50. The 33× gap says 3% of the audience pays.' },
      { term: 'Paying share', def: 'The share of active users who made at least one purchase in a period. It links ARPU and ARPPU: ARPU equals the paying share times ARPPU.', formula: 'paying share = payers / active users', aliases: ['payer conversion', 'conversion to payer'], metric: 'paying-share', id: 'paying-share', cat: 'revenue', case: 'A game had 200,000 monthly actives and 6,000 payers: paying share 3%, ARPPU $50, ARPU $1.50. A discount promo lifted the share to 4%, but ARPPU fell to $35 and ARPU dropped to $1.40: more payers, less money.' },
      { term: 'AOV', def: 'Average order value: revenue divided by the number of orders. Like any average, it is sensitive to outliers.', formula: 'AOV = revenue / number of orders', aliases: ['average check'], metric: 'aov', id: 'aov', cat: 'revenue', case: 'A coffee shop rang up 300 orders worth $3,000 in a day: AOV is $10. Add one $900 corporate order the same day and AOV jumps to almost $13, though regular guests changed nothing. That is why the median is checked next to the mean.' },
      { term: 'Bookings', def: 'The total users actually paid during a period, before revenue is recognized under accounting rules. In games it diverges from revenue because in-game currency is recognized as it gets spent.', aliases: [], metric: 'bookings', id: 'bookings', cat: 'revenue', case: 'In December players bought $1m of gems and spent $600,000 worth of them in the game. December bookings are $1m, while revenue under accounting rules is about $600,000: the rest is recognized when the gems are spent. Promotions are judged by bookings, financial statements use revenue.' },
      { term: 'RPM', def: 'Revenue per mille — what a creator or platform earns per thousand views, after the platform has taken its cut. Unlike CPM, which is what the advertiser pays per thousand impressions.', formula: 'RPM = revenue / views × 1000', aliases: ['revenue per mille'], id: 'rpm', cat: 'revenue', case: 'A video got 200,000 views, and the creator earned $600 after the platform\'s cut. RPM = 600 / 200,000 × 1,000 = $3. Advertisers may have paid $8 per thousand impressions: the platform\'s cut and ad-free views account for the gap.' },
      { term: 'MRR', def: 'Recurring monthly subscription revenue, normalized to a month: an annual contract is divided by 12 and one-off payments are excluded. It decomposes into new, expansion, contraction and churn.', aliases: [], metric: 'mrr', id: 'mrr', cat: 'subscription', case: 'A service has 800 customers on a $20 monthly plan and 100 on a $180 annual plan. MRR = 800 × 20 + 100 × 180 / 12 = $17,500. The annual payment is divided by 12 rather than booked in the month it was paid, otherwise MRR would jump in renewal months.' },
      { term: 'ARR', def: 'Annual recurring revenue from active subscriptions, usually MRR × 12. It describes the current run rate: what the business will earn over the next 12 months if nothing changes.', formula: 'ARR = MRR × 12', aliases: ['annual recurring revenue'], id: 'arr', cat: 'subscription', case: 'A service\'s MRR on September 1 is $17,500, so ARR is $210,000. It is the run rate as of today: if a large customer leaves in October, ARR drops at once, while annual revenue in the books changes only by year end.' },
      { term: 'NRR', def: 'Net revenue retention — what the revenue from a cohort of customers became a year later, counting expansions, downgrades and churn but excluding new customers. Above 100% means growth without new sales.', formula: 'NRR = (starting MRR + expansion − contraction − churn) / starting MRR', aliases: [], metric: 'nrr', id: 'nrr', cat: 'subscription', case: 'A year ago a B2B service\'s customers paid $100,000 a month. Today the same customers pay $115,000: upgrades added $25,000, downgrades took $3,000 and churned customers took $7,000. NRR is 115%, so revenue grows even with no new sales.' },
      { term: 'GRR', def: 'Gross revenue retention — the share of a customer cohort\'s revenue kept a year later, counting downgrades and churn but not expansion. It cannot exceed 100%. It shows how firmly the base holds: in NRR, growth from some customers can hide others leaving.', formula: 'GRR = (starting MRR − contraction − churn) / starting MRR', aliases: ['gross revenue retention'], id: 'grr', cat: 'subscription', case: 'Take the NRR example: a year ago customers paid $100,000 a month, downgrades took $3,000 and churned customers $7,000. GRR = (100 − 3 − 7) / 100 = 90%. Upgrades of $25,000 produced a 115% NRR, yet the service loses a tenth of its base every year.' },
      { term: 'ACV', def: 'Annual contract value — the value of a contract expressed per year: a three-year deal worth 300k has an ACV of 100k. Unlike TCV, which counts the whole sum across the contract term.', formula: 'ACV = total contract value / term in years', aliases: ['annual contract value'], id: 'acv', cat: 'subscription', case: 'A customer signed a three-year deal worth $360,000. ACV is $120,000, TCV is $360,000. A sales team paid on TCV starts selling long contracts at deep discounts, which is why sales targets are usually set in ACV.' },
      { term: 'NPS', def: 'Net promoter score — a loyalty index based on the question "how likely are you to recommend us" on a 0–10 scale. The share of detractors (0–6) is subtracted from the share of promoters (9–10); passives at 7–8 are excluded. The result runs from −100 to +100.', formula: 'NPS = %promoters (9–10) − %detractors (0–6)', aliases: ['net promoter score'], metric: 'nps-csat', id: 'nps', cat: 'referral', case: '1,000 customers answered the recommendation question: 450 gave 9–10, 350 gave 7–8, 200 gave 0 to 6. NPS = 45% − 20% = 25. If half the passives turn into detractors, NPS falls to 7.5 with the same number of promoters.' },
      { term: 'CSAT', def: 'Customer satisfaction score — the share of satisfied answers to "how satisfied are you" after a specific event: an order, a support contact, a delivery. NPS measures attitude to the brand as a whole, CSAT a single interaction.', formula: 'CSAT = ratings of 4–5 / all ratings', aliases: ['customer satisfaction'], metric: 'nps-csat', id: 'csat', cat: 'referral', case: 'After contacting support, 2,400 customers left a rating, and 1,920 gave 4 or 5 out of 5: CSAT is 80%. Broken down by topic, it is only 55% for returns, so look for the cause in the return policy before blaming the agents.' },
      { term: 'K-factor', def: 'Viral coefficient — how many new users one existing user brings in through invites, on average. With K above one a product grows on its own, but in practice K is usually below one and acts as an add-on to other channels.', formula: 'K = invites per user × invite conversion', aliases: ['viral coefficient', 'virality'], metric: 'viral-coefficient', id: 'k-factor', cat: 'referral', case: 'In September 10,000 new users sent 15,000 invites, and 3,000 people signed up from them. K = 1.5 × 0.2 = 0.3: every 10 arrivals bring three more, and about four counting invites from the invitees. That lowers the effective cost of acquisition.' },
      { term: 'LTV', def: 'The total profit a customer brings over their whole life with the product. A rough subscription estimate: average revenue × margin / churn.', formula: 'LTV = average revenue × margin / churn', aliases: ['lifetime value'], metric: 'ltv', id: 'ltv', cat: 'unit', case: 'A subscription costs $10 a month, margin is 60%, monthly churn is 5%. LTV = 10 × 0.6 / 0.05 = $120. If acquiring a customer costs more than $120, every new subscriber loses money.' },
      { term: 'Contribution margin', def: 'Revenue minus the variable costs tied directly to one unit — an order, a ride, a subscription. It shows how much is left to cover fixed costs.', formula: 'contribution margin = revenue − variable costs', aliases: [], metric: 'contribution-margin', id: 'contribution-margin', cat: 'unit', case: 'A $20 pizza order: ingredients $6, courier $3, packaging $0.60, card fees $0.40. Contribution margin is $10 per order, 50%. Kitchen rent and office salaries are not included: they do not depend on the number of orders.' },
      { term: 'LTV / CAC', def: 'The ratio of a customer\'s lifetime value to the cost of acquiring them. It shows whether growth pays off: 3 or more is a common benchmark, and below 1 every new customer loses money.', formula: 'LTV / CAC', aliases: ['ltv cac', 'ltv to cac'], metric: 'ltv-cac', id: 'ltv-cac', cat: 'unit', case: 'A subscriber\'s LTV is $120 and CAC is $30: LTV/CAC = 4. A channel with a $80 CAC brings the same subscribers at a ratio of 1.5, growing revenue while adding almost no profit.' },
      { term: 'Payback period', def: 'CAC payback — how many months a customer has to pay before the gross profit from them covers CAC. The shorter it is, the less cash is tied up in growth and the sooner it can be reinvested in acquisition.', formula: 'payback = CAC / (ARPU × margin)', aliases: ['cac payback'], metric: 'payback-period', id: 'payback', cat: 'unit', case: 'CAC is $30, the subscription is $10 a month at a 60% margin: a customer brings $6 of gross profit a month and pays back in 5 months. At 5% monthly churn about 81% of customers make it to month five, so for the cohort as a whole payback comes later.' },
      { term: 'GMV', def: 'The total value of all goods sold through the platform in a period, before commissions, discounts, cancellations and returns. This is turnover, not revenue: the platform earns only its cut of GMV.', aliases: ['turnover'], metric: 'gmv', id: 'gmv', cat: 'platform', case: 'In a month buyers placed $50m of orders on a marketplace, and $4m of that was cancelled or returned. GMV is $50m, counted before cancellations and returns. Net sales of $46m sit next to it, otherwise a promo with mass cancellations looks like growth.' },
      { term: 'Take Rate', def: 'The share of GMV the platform keeps as commissions and paid services. GMV of 10bn at a 5% take rate is 500m of revenue.', formula: 'take rate = platform revenue / GMV', aliases: ['commission'], metric: 'take-rate', id: 'take-rate', cat: 'platform', case: 'On $50m of GMV a marketplace earned $6m in commissions and $1.5m from seller ads. Take rate = 7.5 / 50 = 15%. When it rises, selling on the platform gets more expensive, so it is watched together with seller churn.' },
      { term: 'TPV', def: 'Total payment volume — the total value of payments processed through the platform in a period. For fintech it plays the role GMV plays for a marketplace: it is flow, not income.', aliases: ['total payment volume'], metric: 'tpv', id: 'tpv', cat: 'platform', case: 'A payment service processed $3bn in a quarter. At an average fee of 1.2%, its income is $36m. If TPV grew while the fee fell, income can stay flat, so both numbers are tracked.' },
      { term: 'GBV', def: 'Gross booking value — the total value of services booked in a period: flights, hotels, tours. For travel it is what GMV is for a marketplace.', aliases: ['gross booking value'], id: 'gbv', cat: 'platform', case: 'An online travel agency sold $200m of flights, hotels and tours over the summer. That is GBV. If 15% of bookings get cancelled, net GBV is $170m, and the agency\'s income is only its commission on that amount.' },
      { term: 'Fulfillment / Match Rate', def: 'The share of requests that reached a successful outcome: the order delivered, the ride taken, demand matched to supply. A measure of the balance between supply and demand on the platform.', formula: 'match rate = successfully closed requests / all requests', aliases: ['matching'], id: 'match-rate', cat: 'platform', case: 'On a Friday evening a ride-hailing service got 50,000 requests and found a car for 42,000. Match rate is 84%, while on weekdays it holds around 95%. The Friday dip points to a driver shortage at peak hours, and the fix is bonuses for evening shifts.' },
      { term: 'Cancellation rate', def: 'The share of orders cancelled after being placed, by the customer, the seller or the service. It is broken down by initiator and reason: a cancellation for an out-of-stock item and one for slow delivery need different fixes.', formula: 'cancellation rate = cancelled orders / placed orders', aliases: ['cancellations'], metric: 'cancellation-rate', id: 'cancellation-rate', cat: 'platform', case: 'In a week a delivery service got 50,000 orders and 2,500 were cancelled: 5%. Restaurants cancelled 1,500 over sold-out dishes, customers 700 after the ETA slipped, the service 300 on suspected fraud. Syncing restaurant stop lists closes the largest part.' },
      { term: 'Same-store sales', def: 'Sales of comparable locations: only the stores or restaurants open in both periods being compared. It strips out the effect of new openings. Reported as LFL (like-for-like).', aliases: ['LFL', 'like-for-like'], metric: 'same-store-sales', id: 'same-store-sales', cat: 'platform', case: 'Over a year a pizza chain\'s sales grew 25%, but 30 new locations opened in that time. In the 120 locations open both years, sales grew 4%. Those 4% are the same-store growth: it shows whether the business grows without new openings.' },
      { term: 'ETA', def: 'Estimated time of arrival — the forecast for when a courier, driver or order will arrive. What is measured is not only the duration but the accuracy of the forecast.', aliases: ['estimated time of arrival'], metric: 'on-time-delivery', id: 'eta', cat: 'platform', case: 'The app promised delivery in 30 minutes and the courier arrived in 38. For one order that is an 8-minute error. The metric is the share of orders that arrived no later than promised plus 5 minutes, say 85% for the week. An optimistic ETA helps sell the order but lowers that share and repeat purchases.' },
      { term: 'B2B / B2C', def: 'Business-to-business and business-to-consumer — selling to companies or directly to end users. B2B has few deals and a long cycle with group decision-making; B2C has many fast transactions.', aliases: ['b2b', 'b2c'], id: 'b2b-b2c', cat: 'concepts' },
      { term: 'SKU', def: 'Stock keeping unit — one distinct product variant with a unique set of attributes: a red T-shirt in size M and the same shirt in size L are two different SKUs. The SKU count describes assortment breadth.', aliases: ['stock keeping unit'], id: 'sku', cat: 'concepts' },
      { term: 'FBO', def: 'A fulfillment model where stock sits in the marketplace warehouse ahead of time and the platform itself stores, picks and delivers it. The opposite model is FBS, where goods stay with the seller and ship per order.', aliases: ['fulfillment by operator'], id: 'fbo', cat: 'concepts' },
      { term: 'KYC', def: 'Know Your Customer — the mandatory identity check before opening an account or processing transactions, required by regulators to fight money laundering.', aliases: ['know your customer'], id: 'kyc', cat: 'concepts' },
      { term: 'Interchange', def: 'An interbank fee: the acquiring bank pays it to the issuing bank on every card transaction. The card network sets the rate, while the issuer collects it.', aliases: ['interchange fee'], id: 'interchange', cat: 'concepts' },
      { term: 'UA', def: 'User acquisition — the function responsible for paid growth: budgets, channels, creatives and media buying.', aliases: ['user acquisition'], id: 'ua', cat: 'concepts' },
      { term: 'F2P', def: 'Free-to-play — a model where the product is free for everyone and revenue comes from a small share of payers, typically 1–5%.', aliases: ['free-to-play'], id: 'f2p', cat: 'concepts' },
      { term: 'SEM', def: 'Search engine marketing — paid promotion in search results, i.e. keyword advertising. Unlike SEO, it works only while the budget lasts.', aliases: ['search engine marketing'], id: 'sem', cat: 'concepts' },
      { term: 'SEO', def: 'Search engine optimization — the work of getting pages to rank higher in unpaid search results, through content, technical health and links.', aliases: ['search engine optimization'], metric: 'seo-visibility', id: 'seo', cat: 'concepts' },
      { term: 'LMS', def: 'Learning management system — the platform that hosts courses, tracks learners and collects completion statistics.', aliases: ['learning management system'], id: 'lms', cat: 'concepts' },
    ],
  },
  {
    group: 'Data engineering',
    categories: [
      { id: 'storage', title: 'Storage and data modeling', desc: 'How data is structured and where it lives' },
      { id: 'pipelines', title: 'Loading and pipelines', desc: 'How data gets from sources to marts' },
      { id: 'dq', title: 'Quality and reliability', desc: 'How to know the data can be trusted' },
    ],
    terms: [
      { term: 'ETL / ELT', def: 'The three steps of delivering data: extract from the source, transform it, load it into the warehouse. ETL transforms before loading; ELT does it inside the warehouse using its own compute — the second order took over once computing inside the warehouse became cheaper than computing next to it.', aliases: ['ETL', 'ELT', 'pipeline'], cat: 'pipelines' },
      { term: 'Data warehouse (DWH)', def: 'A database built for analytical questions rather than for running an application: sources are reconciled into one shape, history is kept, and queries read many rows and few columns.', aliases: ['DWH', 'warehouse'], cat: 'storage' },
      { term: 'Data mart', def: 'A prepared table for one area of questions: orders by day, users by cohort. It is built from raw data in advance so analysts do not repeat the same logic in every query — and do not get a slightly different number every time.', aliases: ['mart', 'data mart'], cat: 'storage' },
      { term: 'Granularity', def: 'What one row of a table means: an order, a line in an order, or a user-day. Until that is said out loud, any sum or average over the table may be counting something other than you think.', aliases: ['grain', 'granularity'], cat: 'storage' },
      { term: 'Partitioning', def: 'Splitting a table physically by the value of a column — usually a date. A one-week query then reads seven chunks instead of the whole history; without it, query cost grows with the size of the data.', aliases: ['partition'], cat: 'storage' },
      { term: 'Idempotency', def: 'The property of an operation returning the same result when it runs again. For a data load it means that rerunning yesterday does not duplicate rows — and rerunning always happens sooner or later.', aliases: ['idempotent', 'rerun'], cat: 'pipelines' },
      { term: 'Slowly changing dimension (SCD)', def: 'A way of keeping the history of a reference table: when an attribute changes, the old row is closed with a date instead of being overwritten, and a new one appears beside it. Otherwise past reports change retroactively along with the reference data.', aliases: ['SCD', 'change history'], cat: 'storage' },
      { term: 'Star schema', def: 'A warehouse model with a fact table at the centre (events with numbers: sales, clicks) surrounded by dimension tables (product, customer, date). A snowflake is the same star with dimensions split further into related tables.', aliases: ['snowflake', 'facts and dimensions'], cat: 'storage' },
      { term: 'Data contract', def: 'An agreement with a source about the fields, types and delivery times of data, written down so that a breach is detected automatically. It replaces the usual scenario where a column gets renamed and you find out from a mismatch in a report.', aliases: ['contract'], cat: 'dq' },
      { term: 'Data lineage', def: 'The traceable chain behind a column: source, intermediate transformations, mart. You need it to know what breaks when a source changes, and who is affected.', aliases: ['lineage', 'provenance'], cat: 'dq' },
      { term: 'Orchestration', def: 'Managing the order of loading steps: what depends on what, on which schedule it runs, how many times to retry on failure and who gets notified. Tools such as Airflow or Dagster describe that arrangement as a graph of tasks.', aliases: ['orchestration', 'Airflow', 'Dagster', 'DAG'], cat: 'pipelines' },
      { term: 'Incremental load', def: 'Loading only new and changed rows instead of reloading the whole history. It needs a change marker (an update timestamp or a version) and idempotency: rerunning the same day must not duplicate rows.', aliases: ['incremental', 'incremental load', 'delta load'], cat: 'pipelines' },
      { term: 'Columnar format (Parquet)', def: 'Storing a table by columns rather than by rows. An analytical query reads two columns out of fifty and never touches the rest, so the volume read drops several times over; compression also works better, because one column holds uniform values.', aliases: ['Parquet', 'ORC', 'columnar'], cat: 'storage' },
      { term: 'Schema evolution', def: 'Changes to the columns or types of a source over time: a field added, renamed, retyped. A load has to survive an added field without breaking, while renames and type changes need a decision in advance, otherwise historical data stops matching the new data.', aliases: ['schema evolution', 'schema drift'], cat: 'dq' },
      { term: 'Data layers', def: 'Splitting the warehouse into processing levels: the raw layer mirrors the source as it came, the cleaned layer fixes types and removes junk, the marts hold tables ready to use. The rule is simple: any lower layer can be recomputed, so raw data is never overwritten.', aliases: ['data layers', 'raw staging marts', 'staging'], cat: 'storage' },
      { term: 'dbt', def: 'A tool where data transformations are written as ordinary SELECT queries in a repository: with versions, tests, documentation and a dependency graph between models. It turns a pile of scattered scripts into a project you can build with one command.', aliases: ['dbt', 'data build tool', 'transformations as code'], cat: 'pipelines' },
      { term: 'Data quality tests', def: 'Automatic checks on a table after loading: the key is unique, required fields are not empty, values fall inside an allowed range, foreign keys point at rows that exist. They catch a break before anyone sees it in a report.', aliases: ['data tests', 'data quality', 'unique not null'], cat: 'dq' },
      { term: 'Data freshness', def: 'How far the data in a table lags behind the source and at what time yesterday shows up. It is checked separately from completeness: a table can refresh on time and still bring only half the rows.', aliases: ['freshness', 'data freshness', 'lag'], cat: 'dq' },
      { term: 'Streaming', def: 'Processing events as they arrive rather than in a batch once an hour or once a day. Kafka takes the stream and keeps it as a log; consumers read from it independently and at their own speed. It is needed where a decision takes seconds: fraud checks, feeds, dynamic pricing.', aliases: ['streaming', 'Kafka', 'real time'], cat: 'pipelines' },
      { term: 'Distributed computing', def: 'Processing data on a cluster of machines when a table does not fit in the memory of one server. Spark splits the work into parts and spreads them across nodes. The price is the complexity of running and debugging it, so at volumes an ordinary database handles, a cluster costs more than it gives.', aliases: ['Spark', 'distributed computing', 'cluster', 'Hadoop'], cat: 'pipelines' },
      { term: 'Lakehouse (Iceberg, Delta)', def: 'A table format on top of files in object storage that adds what plain files lack: transactions, schema evolution, snapshots and querying the data as of a point in the past. It gives warehouse properties at the cost of a file lake.', aliases: ['Iceberg', 'Delta Lake', 'lakehouse', 'Hudi', 'data lake'], cat: 'storage' },
      { term: 'Data SLA', def: 'A written promise to the consumer: by what time a mart is ready, for which period it is complete and what happens when that is missed. Without it, an argument about a broken report comes down to who expected what.', aliases: ['SLA', 'data SLA', 'service level agreement'], cat: 'dq' },
    ],
  },
  {
    group: 'SQL and queries',
    terms: [
      { term: 'JOIN', def: 'Combining rows from two tables on a condition. INNER keeps only matched pairs; LEFT keeps every row of the left table and fills NULLs where no match exists. If one left row matches several rows on the right, the left row multiplies: that is where unordered duplicates come from.', aliases: ['inner join', 'left join', 'joining tables'] },
      { term: 'CTE (common table expression)', def: 'A named intermediate query declared with WITH and used afterwards like an ordinary table. It breaks a long query into steps that read top to bottom, instead of subqueries nested inside subqueries.', aliases: ['CTE', 'WITH', 'subquery'] },
      { term: 'Window function', def: 'A function that computes a value across a group of rows without collapsing them: every row keeps its own value and gains the result over the window. ROW_NUMBER numbers rows inside a group, LAG takes the previous row’s value, SUM OVER gives a running total.', formula: 'SUM(x) OVER (PARTITION BY g ORDER BY t)', aliases: ['window function', 'ROW_NUMBER', 'LAG', 'OVER', 'PARTITION BY'] },
      { term: 'Aggregation and GROUP BY', def: 'Collapsing many rows into one per combination of grouping columns: sum, average, count. WHERE filters rows before aggregation; HAVING selects among the groups after it.', aliases: ['GROUP BY', 'HAVING', 'aggregate'] },
      { term: 'NULL', def: 'A marker meaning "value unknown", not zero and not an empty string. Any comparison with NULL yields unknown, so a condition like "field is not X" silently drops rows where the field is empty; it has to be checked separately with IS NULL.', aliases: ['null', 'missing value', 'IS NULL'] },
      { term: 'Query plan', def: 'A description of how the database intends to run a query: in which order to read tables, whether to use an index, how to join. You read it when a query is slow: the reason is almost always visible in the plan rather than in the query text.', aliases: ['EXPLAIN', 'query plan', 'explain analyze'] },
      { term: 'Index', def: 'An extra structure that lets the database find the rows it needs without reading the whole table. It speeds up lookups on the indexed columns and slows down writes, because every change to the data updates the index too.', aliases: ['index', 'indexes'] },
    ],
  },
]
